from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class PlanValidationASMV1(SchemaObject):
    action_id = SchemaField(name="action_id", not_null=True)
    error_message = SchemaField(name="error_message")
    links = SchemaField(name="links")
    status = SchemaField(name="status", not_null=True)
    validation_id = SchemaField(name="validation_id")

    def __init__(self, action_id, error_message, links, status, validation_id):
        self.action_id = action_id
        self.error_message = error_message
        self.links = links
        self.status = status
        self.validation_id = validation_id

        super(PlanValidationASMV1, self).__init__()
